"""Render the experiment-by-experiment PI review. Reads saved evidence; executes no studies."""
from pathlib import Path
import hashlib, html, json
from urllib.parse import quote

O = Path(__file__).resolve().parent
R = O.parent
H = lambda v: html.escape(str(v), quote=True)
read = lambda name: json.loads((O / name).read_text())
files = ['scientific-root.json', 'scientific-phantom-quorum.json', 'scientific-regrowth-avalon.json', 'scientific-sizing.json', 'scientific-theseus-healing.json', 'scientific-immune-guide.json', 'scientific-heterogeneous.json']
reviews = []
for name in files:
    value = read(name)
    reviews.extend(value['reviews'] if isinstance(value, dict) else value)
byid = {x['id']: x for x in reviews}
assert len(byid) == len(reviews)
required = ['id','name','evidence_class','decision','interest','robustness','scenario_quality','scenarios','controls','parameters','next_study','sources']
for x in reviews:
    assert all(x.get(k) for k in required), x['id']
    assert set(x['scenario_quality']) == {'size','challenge','complexity','realism','definition'}
portfolio = read('scientific-portfolio.json')
synthesis = read('scientific-synthesis.json')
groups = synthesis['groups']; areas = synthesis['areas']
assert len(portfolio) == 16 and len(areas) == 8 and len(groups) == 11
assigned = [i for g in groups for i in g['review_ids']]
assert len(assigned) == len(set(assigned)) and set(assigned) == set(byid)

def link(path, label=None):
    if path.startswith(('https://','http://','codex://','#')):
        href = path
    elif path.startswith('/'):
        href = 'file://' + quote(path, safe='/')
    else:
        href = '../' + quote(path, safe='/')
    return f'<a href="{H(href)}">{H(label or path)}</a>'

def para(label, value):
    return f'<p><strong>{H(label)}.</strong> {H(value)}</p>'

def listing(value):
    return '<ul>' + ''.join(f'<li>{H(x)}</li>' for x in value) + '</ul>' if isinstance(value,list) else '<p>'+H(value)+'</p>'

def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+H(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def sources(items):
    return '<div class="sources"><h4>Evidence and design sources</h4>'+''.join('<p>'+link(s['path'])+(' · line '+str(s['line']) if s.get('line') else '')+'<br>'+H(s.get('detail',''))+'</p>' for s in items)+'</div>'

parts = ['''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grove Swarm · Experiment-by-experiment PI review</title><style>
:root{--paper:#f7f5ed;--ink:#19352f;--muted:#59685f;--line:#d3dbd0;--accent:#185f46;--pale:#e8eee3;--white:#fffef9;--warm:#f2e6d8}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,sans-serif}a{color:var(--accent);text-underline-offset:3px}a:hover{text-decoration-thickness:2px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #b27608;outline-offset:4px}header,main,footer{max-width:1160px;margin:auto;padding:40px 28px}header{padding-top:64px;padding-bottom:30px}h1,h2,h3,h4{line-height:1.2;letter-spacing:-.025em}h1,h2{font-family:Georgia,serif;font-weight:500}h1{font-size:clamp(42px,6vw,72px);margin:10px 0 24px;max-width:970px}h2{font-size:clamp(30px,4vw,43px);margin:0 0 24px}h3{font-size:22px}h4{font-size:18px;margin:30px 0 12px}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:12px;font-weight:750;color:var(--accent)}.lede{font-size:22px;max-width:940px;line-height:1.5}.small{font-size:13px;color:var(--muted)}.nav{position:sticky;top:0;z-index:5;display:flex;overflow:auto;gap:26px;padding:13px max(22px,calc((100vw - 1104px)/2));background:var(--ink);white-space:nowrap}.nav a{color:white;text-decoration:none;font-size:14px}.stamp{border-top:1px solid var(--line);padding-top:16px}.section{margin:0 0 60px;padding-top:20px}.note{background:var(--pale);border-left:4px solid var(--accent);padding:18px 22px}.warm{background:var(--warm);border-color:#9b6339}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:var(--white);padding:24px;border:1px solid var(--line);border-radius:8px;min-width:0}.card h3{margin:9px 0 15px}.tag{display:inline-block;font-size:11px;font-weight:750;letter-spacing:.06em;text-transform:uppercase;padding:3px 9px;border:1px solid var(--line);border-radius:4px;background:var(--pale);color:var(--accent)}.card p{margin:10px 0}.jump{font-size:14px;font-weight:600}.study,.proposal{border:1px solid var(--line);border-radius:6px;background:var(--white);margin:14px 0;overflow:hidden}summary{cursor:pointer;padding:20px 22px;line-height:1.45;font-weight:650;list-style-position:inside}.summary-decision{display:block;font-weight:400;font-size:14px;color:var(--muted);margin:10px 0 0 19px}.inside{padding:0 24px 24px}.inside>h3{font-size:25px;margin-top:18px}.table-wrap{overflow-x:auto;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:14px;text-align:left}th,td{vertical-align:top;border-bottom:1px solid var(--line);padding:14px 12px;min-width:130px}th{font-weight:650;background:var(--pale)}td:first-child{font-weight:600}table p{margin:0}.sources{border-top:1px solid var(--line);margin-top:25px;padding-top:3px;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.sources h4{font-size:14px}.toolbar{display:flex;align-items:end;flex-wrap:wrap;gap:16px;margin:26px 0}.toolbar label{font-size:12px;font-weight:650;display:flex;flex-direction:column;gap:5px}.toolbar input{width:310px;max-width:100%}input,select,button{font:inherit;color:var(--ink);border:1px solid #8da095;background:var(--white);padding:9px 12px;border-radius:4px;max-width:100%}button{cursor:pointer;font-size:13px}.group-title{border-top:2px solid var(--accent);padding-top:20px;margin-top:38px}.group-title h3{margin:5px 0}.decision{font-size:18px}.five{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 24px}.five p{margin:8px 0}.criteria{counter-reset:c}.criteria p{padding-left:0}.review-links{display:flex;flex-wrap:wrap;gap:10px 18px}.empty{padding:24px;border:1px dashed var(--line)}[hidden]{display:none!important}footer{font-size:13px;border-top:1px solid var(--line)}@media(max-width:650px){header,main,footer{padding-left:20px;padding-right:20px}.grid,.five{grid-template-columns:1fr}.lede{font-size:19px}.card{padding:20px}.inside{padding:0 17px 20px}summary{padding:18px 16px}.toolbar{align-items:stretch}.toolbar label{width:100%}.toolbar input{width:100%}.nav{gap:22px}.section{margin-bottom:38px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.nav,.toolbar{display:none}.inside{display:block!important}.study,.proposal{break-inside:auto}body{font-size:11pt;background:white}header,main{max-width:none;padding:15px}a{color:inherit}.card{break-inside:avoid}}
</style></head><body><header><p class="eyebrow">Grove Swarm Research · Scientific review · 4 October 2026</p><h1>What each experiment can establish</h1><p class="lede">The strongest next step is a sharper causal test. Several current studies are good instruments or useful negative results; none yet establishes a general swarm advantage. This review assesses the ten named projects individually, including their scenarios, controls, parameters and next decisive comparison.</p>''']
parts.append(f'<p class="stamp small"><strong>{len(groups)-1} named projects · {len(reviews)} study/version reviews · {sum(len(x["scenarios"]) for x in reviews)} scenario/condition assessments · 16 original proposals · 8 focus areas.</strong><br>PI judgments and proposed next studies are editorial recommendations. Completed runs, scripted fixtures and unrun proposals retain separate evidence labels.</p></header>')
parts.append('<nav class="nav" aria-label="Review sections"><a href="#overview">Ten projects</a><a href="#criteria">Scientific standard</a><a href="#studies">Detailed reviews</a><a href="#areas">Research areas</a><a href="#portfolio">Sixteen proposals</a><a href="#scope">Scope & sources</a><a href="index.html">Original audit</a></nav><main>')
parts.append('<section class="section" id="overview"><p class="eyebrow">01 / Decisions at a glance</p><h2>The ten projects you named</h2><p>Names follow the task list in your screenshot. Each card opens its detailed reviews. Historical versions stay visible so improvements are not confused with evidence already obtained.</p><div class="grid">')
for i,g in enumerate(groups[:-1],1):
    parts.append(f'<article class="card"><span class="tag">{i:02} · {H(g["status"])}</span><h3>{H(g["title"])}</h3><p>{H(g["judgment"])}</p><p class="review-links">'+''.join(link('#'+rid,byid[rid]['name']) for rid in g['review_ids'])+'</p></article>')
parts.append('</div><p class="note">The key scaling question is whether additional agents create useful private information, complementary abilities or coordination demands. More copies of a solved task do not make the research deeper. Start at the smallest scale that exposes the mechanism, then test transfer and scaling where the claim requires them.</p></section>')
parts.append('''<section class="section" id="criteria"><p class="eyebrow">02 / A standard that fits a small lab</p><h2>Interesting, identifiable and consequential</h2><div class="criteria"><p><strong>Interesting.</strong> Name the result that would change a practical decision or distinguish competing explanations. A biological analogy, vivid failure or increase in agreement is a starting point. Novelty requires a close methods comparison; this review does not certify it from an abstract collection.</p><p><strong>Robust.</strong> Count independently constructed worlds, tasks or adapted lineages. Repeated agents, messages, forks, seeds on the same tiny fixture and generations are dependent. Pair conditions at the level randomized; preserve family and lineage structure in uncertainty estimates. Size studies from a useful-effect margin and pilot variability, not a universal minimum number of agents.</p><p><strong>Challenging and defined.</strong> Qualify clean competence and show room above the baseline. The task should survive an exact-rule, equally informed single-controller and simple operational baseline. Increasing ambiguity without specifying what an agent could know creates an unanswerable task, not a stronger one.</p><p><strong>Controlled.</strong> State which of information, calls, tokens, tools, memory, time and money are held equal, charged, or deliberately changed. Match information at the causal branch point. In adaptive exploration, changed observations are part of the mechanism; measure them instead of forcing them equal after treatment.</p><p><strong>Realistic enough.</strong> Preserve consequential constraints and costs: wrong authorization, missed deadlines, lost evidence, false alarms, interrupted work. Add external inputs after a clean mechanism works. A task can be intentionally synthetic, provided claims stay at that level.</p><p><strong>Small enough to finish.</strong> Freeze one main comparison and a few necessary controls. Essential identification axes are marked separately from later stress tests throughout this report. A null or a deterministic solution is an acceptable result; it should stop unnecessary expansion.</p></div><div class="note"><strong>Agent identity is an experimental variable.</strong> Use the <a href="../agent-experiment-guide/AGENT-LIFECYCLE.md">agent definition and lifecycle contract</a>: versioned definition, actual initialized context, private/shared memory ownership, access rules, reset/fork semantics and logged state evolution. Reliable initialization means the same declared setup; it does not promise identical hosted-model output. Keep intended configuration separate from the receipt of what each actor actually received.</div></section>''')
parts.append('<section class="section" id="studies"><p class="eyebrow">03 / Full scientific assessments</p><h2>Experiment and scenario reviews</h2><p>Every review covers interest, robustness, scale, challenge, complexity, realism, definition, controls, key parameters and a bounded next study.</p><div class="toolbar"><label>Search the full assessments<input type="search" id="study-search" placeholder="Try memory, quorum, capability…"></label><label>Project<select id="study-group"><option value="">All projects</option>'+''.join(f'<option value="{g["id"]}">{H(g["title"])}</option>' for g in groups)+'</select></label><button id="expand" type="button">Expand visible reviews</button><button id="reset" type="button">Clear filters</button><span id="study-count" role="status" aria-live="polite"></span></div><p class="empty" id="empty" hidden>No matching reviews. Clear the search or choose another project.</p>')
for g in groups:
    parts.append(f'<div class="review-group" data-group="{g["id"]}"><div class="group-title"><p class="eyebrow">{H(g["status"])}</p><h3>{H(g["title"])}</h3></div>')
    for rid in g['review_ids']:
        x=byid[rid]
        parts.append(f'<details class="study" id="{rid}" data-group="{g["id"]}"><summary>{H(x["name"])}<span class="summary-decision">{H(x["decision"])}</span></summary><div class="inside"><p class="note"><strong>Evidence status.</strong> {H(x["evidence_class"])}</p><h3>Scientific interest</h3>'+''.join(para(label,x['interest'][key]) for key,label in [('judgment','PI judgment'),('why','Why it matters'),('novelty_boundary','Novelty boundary')]))
        parts.append('<h3>How robust is the evidence?</h3>'+''.join(para(label,x['robustness'][key]) for key,label in [('supported','Supported'),('unsupported','Not established'),('unit','Independent unit'),('independent_variation','Actual variation'),('assessment','Assessment')]))
        parts.append('<h3>Is the scenario adequate?</h3><div class="five">'+''.join(para(k.capitalize(),v) for k,v in x['scenario_quality'].items())+'</div>')
        parts.append('<h3>Each scenario or condition</h3>'+table(['Scenario / condition','Assessment','Improvement'],[[H(s['name']),H(s['assessment']),H(s['improvement'])] for s in x['scenarios']]))
        parts.append('<h3>Controls and competing explanations</h3>'+''.join('<h4>'+label+'</h4>'+listing(x['controls'][k]) for k,label in [('retain','Keep'),('missing','Add or resolve'),('confounds','Threats to interpretation')]))
        parts.append('<h3>Parameters worth testing</h3>'+table(['Parameter','Current setting','Priority','Proposed variation and reason'],[[H(p['parameter']),H(p['current']),H(p['priority']),H(p['proposed_variation'])+'<br><br>'+H(p['reason'])] for p in x['parameters']]))
        parts.append('<h3>The next decisive study</h3>'+''.join(para(label,x['next_study'][key]) for key,label in [('question','Question'),('primary_contrast','Primary contrast'),('endpoint','Outcome'),('unit','Unit'),('design','Bounded design'),('go_no_go','Continue or stop')])+sources(x['sources'])+'</div></details>')
    parts.append('</div>')
parts.append('</section><section class="section" id="areas"><p class="eyebrow">04 / Cross-project coverage</p><h2>Eight research focus areas</h2><p>These are the project’s cross-cutting navigation areas, not eight additional independent experiments. One study may inform several areas without becoming multiple replications.</p>')
for a in areas:
    parts.append('<article class="card" style="margin:16px 0"><h3>'+H(a['name'])+'</h3>'+para('Assessment',a['assessment'])+para('Scientific priority',a['priority'])+'<p class="small">'+ ' · '.join(link('#'+i,byid[i]['name']) for i in a['review_ids'])+'</p></article>')
parts.append('</section><section class="section" id="portfolio"><p class="eyebrow">05 / Original idea portfolio</p><h2>All sixteen original proposals</h2><p>These assessments preserve the original portfolio while directing related ideas toward the developed experiments above. Each has its own judgment, scenario critique, parameter priorities, controls and next step. Related evidence is identified; an attractive proposal is not treated as a completed result.</p>')
for x in portfolio:
    parts.append(f'<details class="proposal" id="{x["id"]}"><summary>{H(x["name"])}<span class="summary-decision">{H(x["decision"])}</span></summary><div class="inside">')
    for key,label in [('interest','Scientific interest'),('robustness','Evidence and robustness'),('scenario_adequacy','Scenario adequacy'),('question','Current recommended question'),('comparison','Comparison'),('endpoint','Outcome')]:
        parts.append(para(label,x[key]))
    parts.append('<h4>Parameters</h4>'+listing(x['key_parameters'])+para('Controls',x['controls'])+para('Next step',x['next_step']))
    if x.get('earlier_reframing'):
        parts.append('<p class="small">Earlier framing is preserved in the JSON source as history; the recommendation above supersedes it.</p>')
    parts.append(sources(x['sources'])+'</div></details>')
parts.append('</section><section class="section" id="scope"><p class="eyebrow">06 / Reading depth and provenance</p><h2>What this review covers</h2>'+para('Scope',synthesis['scope']))
parts.append('<p>The <a href="index.html">original audit</a> covers 1,331 unique local project files across its two recorded snapshots, with 57 prioritized findings. Its raw-evidence checks remain the basis for claims marked independently reconstructed. This scientific addendum adds per-experiment judgments and pinned linked-repository documents; it does not expand that original file-count claim or imply that every remote run was independently replayed.</p><p>Antsy and historical/revised external-influence figures are reported by their source authors and checked against the documents. Raw model execution was not repeated. New proposals have no scientific outcomes. The Phantom Coast and Quorum of Mirrors handoffs were traced to their original documents because their dedicated tasks had no independent results. The active heterogeneous-swarms revision is frozen at 03:23:55 UTC on 4 October; subsequent changes are outside this review. A late Phantom Coast PC-1 plan was additionally read and frozen at 03:40:18 UTC; concurrent code/tests and the new whole-repository checkout are outside that bounded plan review.</p><p>Source reading depth is recorded. Referenced external literature is not automatically full-read because a project document cites it. Interest and prioritization are PI judgments, not calibrated numeric scores or a completed novelty certification.</p>')
parts.append('<div class="note warm"><strong>No new experiments were launched for this review.</strong> Proposed next studies are recommendations, not preregistrations. Before experimental implementation, write the plan; before any run, publish and verify the immutable plan and condition-specific TLDR required by AGENTS.md. This addendum adds scientific review artifacts and navigation; it does not silently change historical results or repair the remaining runner defects.</div>')
parts.append('<h3>Saved sources and review data</h3><ul>'+''.join('<li>'+link('review-2026-10-04/'+f,f)+'</li>' for f in ['scientific-review.json','scientific-source-register-expanded.json','scientific-handoff-sources.json','scientific-sources-live/heterogeneous-frontiers-cutoff.json','scientific-sizing-thread-check.json','scientific-phantom-delta.json','scientific-presentation-checks.json','scientific-portfolio.json','scientific-synthesis.json','scientific-delivery-checks.json'])+'</ul></section></main><footer>Grove Swarm Research · PI scientific review · Generated from local review records. '+link('review-2026-10-04/index.html','Return to evidence and implementation audit')+'</footer>')
parts.append('''<script>
const studies=[...document.querySelectorAll('.study')], groups=[...document.querySelectorAll('.review-group')];
const search=document.querySelector('#study-search'),group=document.querySelector('#study-group'),count=document.querySelector('#study-count');
function filter(){const q=search.value.toLocaleLowerCase().trim();let n=0;for(const d of studies){d.hidden=!!((group.value&&d.dataset.group!==group.value)||(q&&!d.textContent.toLocaleLowerCase().includes(q)));if(!d.hidden)n++;}for(const g of groups)g.hidden=![...g.querySelectorAll('.study')].some(d=>!d.hidden);count.textContent=`${n} of ${studies.length} reviews`;document.querySelector('#empty').hidden=n!==0;}
search.addEventListener('input',filter);group.addEventListener('change',filter);document.querySelector('#reset').addEventListener('click',()=>{search.value='';group.value='';filter();});
document.querySelector('#expand').addEventListener('click',()=>studies.filter(d=>!d.hidden).forEach(d=>d.open=true));
function reveal(){const id=decodeURIComponent(location.hash.slice(1));const e=document.getElementById(id);if(!e)return;if(e.matches('details')){if(e.classList.contains('study')){search.value='';group.value='';filter();}e.open=true;requestAnimationFrame(()=>e.scrollIntoView());}}
addEventListener('hashchange',reveal);addEventListener('beforeprint',()=>document.querySelectorAll('details').forEach(d=>{d.dataset.wasOpen=d.open;d.open=true;}));addEventListener('afterprint',()=>document.querySelectorAll('details').forEach(d=>d.open=d.dataset.wasOpen==='true'));filter();reveal();
</script></body></html>''')
(O/'scientific-review.html').write_text(''.join(parts))
combined = dict(scope=synthesis['scope'], reviews=reviews, groups=groups, focus_areas=areas, original_proposals=portfolio)
(O/'scientific-review.json').write_text(json.dumps(combined,indent=2,ensure_ascii=False)+'\n')
checks = dict(named_projects=10, study_version_reviews=len(reviews), scenario_condition_assessments=sum(len(x['scenarios']) for x in reviews), original_proposals=len(portfolio), cross_cutting_areas=len(areas), unique_ids=True, required_fields=True, coverage_mapping_complete=True, source_inputs={f:hashlib.sha256((O/f).read_bytes()).hexdigest() for f in files+['scientific-portfolio.json','scientific-synthesis.json']}, interpretation='Structural checks only. Browser verification is recorded separately. Scientific recommendations are not executed experiments.')
(O/'scientific-delivery-checks.json').write_text(json.dumps(checks,indent=2)+'\n')
print(json.dumps({k:v for k,v in checks.items() if k!='source_inputs'},indent=2))
